hex_output.c<pre><code>#include &lt;stdio.h&gt;

int main(void)
{
    unsigned int reg = 0x1234ABCD;

    printf("十进制:   %u\n", reg);
    printf("十六进制: %x\n", reg);       // 小写
    printf("十六进制: %X\n", reg);       // 大写
    printf("带前缀:  0x%08X\n", reg);    // 8位补零，带 0x 前缀

    // 打印内存中的字节
    unsigned char data[] = {0xDE, 0xAD, 0xBE, 0xEF};
    printf("数据: ");
    for (int i = 0; i &lt; 4; i++) {
        printf("%02X ", data[i]);
    }
    printf("\n");
    // 输出：数据: DE AD BE EF

    return 0;
}
</code></pre>

scanf_basic.c<pre><code>#include &lt;stdio.h&gt;

int main(void)
{
    int age;
    printf("请输入你的年龄: ");
    scanf("%d", &amp;age);  // 注意：变量前要加 &amp; 符号！
    printf("你 %d 岁了\n", age);

    float height;
    printf("请输入你的身高(米): ");
    scanf("%f", &amp;height);
    printf("你的身高是 %.2f 米\n", height);

    char grade;
    printf("请输入你的等级(A/B/C): ");
    scanf(" %c", &amp;grade);  // %c 前面加空格，跳过上次输入的换行符
    printf("你的等级是 %c\n", grade);

    return 0;
}
</code></pre> <p>scanf 的 &amp; 符号</p> <p><pre><code>int a;
scanf("%d", &amp;a);   // ✅ 正确：&amp; 取变量的地址
scanf("%d", a);    // ❌ 错误：没有 &amp;，程序会崩溃！
</code></pre> <code>scanf</code> 需要知道数据存到哪个地址，所以必须用 <code>&amp;</code> 取地址。 （后面学指针时会深入理解这一点）</p>

