simple_calc.c<pre><code>#include &lt;stdio.h&gt;

int main(void)
{
    double num1, num2;
    char op;

    printf("请输入表达式 (如 3.5 + 2.1): ");
    scanf("%lf %c %lf", &amp;num1, &amp;op, &amp;num2);

    printf("%.2f %c %.2f = ", num1, op, num2);

    switch (op) {
        case '+': printf("%.2f\n", num1 + num2); break;
        case '-': printf("%.2f\n", num1 - num2); break;
        case '*': printf("%.2f\n", num1 * num2); break;
        case '/':
            if (num2 != 0)
                printf("%.2f\n", num1 / num2);
            else
                printf("错误：除数不能为 0\n");
            break;
        default:
            printf("不支持的运算符\n");
    }

    return 0;
}
</code></pre>

