char_type.c<pre><code>#include &lt;stdio.h&gt;

int main(void)
{
    char ch;
    printf("请输入一个字符: ");
    scanf(" %c", &amp;ch);

    if (ch &gt;= 'A' &amp;&amp; ch &lt;= 'Z') {
        printf("'%c' 是大写字母\n", ch);
        printf("对应的小写字母是: '%c'\n", ch + 32);
    } else if (ch &gt;= 'a' &amp;&amp; ch &lt;= 'z') {
        printf("'%c' 是小写字母\n", ch);
        printf("对应的大写字母是: '%c'\n", ch - 32);
