        printf("'%c' 是数字\n", ch);
        printf("数值是: %d\n", ch - '0');
    } else {
        printf("'%c' 是特殊字符 (ASCII: %d)\n", ch, ch);
    }

    return 0;
}
</code></pre>

gpio_config.c<pre><code>#include &lt;stdio.h&gt;

// 模拟 GPIO 模式
#define MODE_INPUT    0
#define MODE_OUTPUT   1
#define MODE_AF       2  // Alternate Function
#define MODE_ANALOG   3

int main(void)
{
    int pin, mode;

    printf("GPIO 引脚配置\n");
    printf("引脚编号 (0-15): ");
    scanf("%d", &amp;pin);

    if (pin &lt; 0 || pin &gt; 15) {
        printf("错误: 引脚号必须在 0~15 之间\n");
        return 1;  // 非零返回值表示错误
    }

    printf("模式选择:\n");
    printf("  0 - 输入模式\n");
    printf("  1 - 输出模式\n");
    printf("  2 - 复用功能\n");
    printf("  3 - 模拟模式\n");
    printf("选择: ");
    scanf("%d", &amp;mode);

    printf("\n配置结果: GPIO Pin %d → ", pin);
    switch (mode) {
        case MODE_INPUT:  printf("输入模式\n"); break;
        case MODE_OUTPUT: printf("输出模式\n"); break;
        case MODE_AF:     printf("复用功能\n"); break;
        case MODE_ANALOG: printf("模拟模式\n"); break;
        default:
            printf("无效模式！\n");
            return 1;
    }

    // 模拟设置寄存器
    unsigned int moder = 0;
    moder |= (mode &lt;&lt; (pin * 2));
    printf("MODER 寄存器值: 0x%08X\n", moder);

    return 0;
}
</code></pre>

sum.c<pre><code>#include &lt;stdio.h&gt;

int main(void)
{
    // 计算 1 + 2 + 3 + ... + 100
    int sum = 0;
    for (int i = 1; i &lt;= 100; i++) {
        sum += i;  // sum = sum + i
    }
    printf("1+2+...+100 = %d\n", sum);  // 5050

    // 计算阶乘 5! = 1×2×3×4×5
    int factorial = 1;
    int n = 5;
    for (int i = 1; i &lt;= n; i++) {
        factorial *= i;
    }
    printf("%d! = %d\n", n, factorial);  // 120

    return 0;
}
</code></pre>

