prime.c<pre><code>#include &lt;stdio.h&gt;

int main(void)
{
    int n;
    printf("输入一个正整数: ");
    scanf("%d", &amp;n);

    if (n &lt;= 1) {
        printf("%d 不是素数\n", n);
        return 0;
    }

    int is_prime = 1;  // 先假设是素数
    for (int i = 2; i * i &lt;= n; i++) {  // 只需检查到 √n
        if (n % i == 0) {
            is_prime = 0;  // 能整除，不是素数
            break;
        }
    }

    printf("%d %s素数\n", n, is_prime ? "是" : "不是");

    return 0;
}
</code></pre>

fibonacci.c<pre><code>#include &lt;stdio.h&gt;

