reverse.c<pre><code>#include &lt;stdio.h&gt;

int main(void)
{
    int num, reversed = 0;
    printf("输入一个整数: ");
    scanf("%d", &amp;num);

    int original = num;
    while (num != 0) {
        reversed = reversed * 10 + num % 10;
        num /= 10;
    }

    printf("%d 翻转后是 %d\n", original, reversed);
    // 输入 12345，输出：54321

    return 0;
}
</code></pre>

