int main(void)
{
    printf("5! = %d\n", factorial(5));          // 120
    printf("2^10 = %d\n", power(2, 10));        // 1024
    printf("GCD(48, 18) = %d\n", gcd(48, 18));  // 6

    // 打印 100 以内的素数
    printf("\n100以内的素数: ");
    int count = 0;
    for (int i = 2; i &lt;= 100; i++) {
        if (is_prime(i)) {
            printf("%d ", i);
            count++;
        }
    }
    printf("\n共 %d 个\n", count);

    return 0;
}

// 阶乘
int factorial(int n)
{
    int result = 1;
    for (int i = 2; i &lt;= n; i++) {
        result *= i;
    }
    return result;
}

// 幂运算
int power(int base, int exp)
{
    int result = 1;
    for (int i = 0; i &lt; exp; i++) {
        result *= base;
    }
    return result;
}

// 最大公约数（辗转相除法）
int gcd(int a, int b)
{
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// 判断素数
int is_prime(int n)
{
    if (n &lt;= 1) return 0;
    for (int i = 2; i * i &lt;= n; i++) {
        if (n % i == 0) return 0;
    }
    return 1;
}
