// ❌ 值传递：无法交换
void swap_wrong(int a, int b)
{
    int temp = a;
    a = b;
    b = temp;
    // 只是交换了副本，原始变量不受影响
}

// ✅ 指针传递：可以交换
void swap(int *a, int *b)
{
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main(void)
{
    int x = 10, y = 20;

    swap_wrong(x, y);
    printf("swap_wrong 后: x=%d, y=%d\n", x, y);  // x=10, y=20（没变）

    swap(&amp;x, &amp;y);    // 传地址
    printf("swap 后: x=%d, y=%d\n", x, y);  // x=20, y=10（交换了）

    return 0;
}
