    gpio_set_mode(&amp;GPIOA, 5, 1);  // PA5 设为输出模式
    gpio_write(&amp;GPIOA, 5, 1);     // PA5 输出高电平

    printf("MODER = 0x%08X\n", GPIOA.MODER);  // 0x00000400
