linked_list.c<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct Node {
    int data;
    struct Node *next;
} Node;

// 头插法
Node *list_push(Node *head, int data)
{
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return head;
    new_node-&gt;data = data;
    new_node-&gt;next = head;
    return new_node;
}

// 尾插法
Node *list_append(Node *head, int data)
{
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return head;
    new_node-&gt;data = data;
    new_node-&gt;next = NULL;

    if (head == NULL) return new_node;

    Node *cur = head;
    while (cur-&gt;next) cur = cur-&gt;next;
    cur-&gt;next = new_node;
    return head;
}

// 打印
void list_print(Node *head)
{
    Node *cur = head;
    while (cur) {
        printf("%d → ", cur-&gt;data);
        cur = cur-&gt;next;
    }
    printf("NULL\n");
}

// 释放整个链表
void list_free(Node *head)
{
    while (head) {
        Node *tmp = head;
        head = head-&gt;next;
        free(tmp);
    }
}

int main(void)
{
    Node *list = NULL;
    list = list_append(list, 10);
    list = list_append(list, 20);
    list = list_append(list, 30);
    list = list_push(list, 5);

    list_print(list);  // 5 → 10 → 20 → 30 → NULL
    list_free(list);
    return 0;
}
</code></pre>

