queue.c<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdbool.h&gt;

#define QUEUE_MAX 100

typedef struct {
    int data[QUEUE_MAX];
    int front, rear;
    int count;
} Queue;

void queue_init(Queue *q) { q-&gt;front = q-&gt;rear = q-&gt;count = 0; }
bool queue_empty(Queue *q) { return q-&gt;count == 0; }
bool queue_full(Queue *q)  { return q-&gt;count == QUEUE_MAX; }

bool queue_enqueue(Queue *q, int val) {
    if (queue_full(q)) return false;
    q-&gt;data[q-&gt;rear] = val;
    q-&gt;rear = (q-&gt;rear + 1) % QUEUE_MAX;
    q-&gt;count++;
    return true;
}

bool queue_dequeue(Queue *q, int *val) {
    if (queue_empty(q)) return false;
    *val = q-&gt;data[q-&gt;front];
    q-&gt;front = (q-&gt;front + 1) % QUEUE_MAX;
    q-&gt;count--;
    return true;
}

int main(void)
{
    Queue q;
    queue_init(&amp;q);

    queue_enqueue(&amp;q, 10);
    queue_enqueue(&amp;q, 20);
    queue_enqueue(&amp;q, 30);

    int val;
    while (!queue_empty(&amp;q)) {
        queue_dequeue(&amp;q, &amp;val);
        printf("%d ", val);  // 10 20 30
    }
    printf("\n");

    return 0;
}
</code></pre>

