singly_linked_list.c<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct Node {
    int data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    int size;
} LinkedList;

// 初始化
void list_init(LinkedList *list) {
    list-&gt;head = NULL;
    list-&gt;size = 0;
}

// 头插
void list_push_front(LinkedList *list, int val) {
    Node *node = (Node *)malloc(sizeof(Node));
    node-&gt;data = val;
    node-&gt;next = list-&gt;head;
    list-&gt;head = node;
    list-&gt;size++;
}

// 尾插
void list_push_back(LinkedList *list, int val) {
    Node *node = (Node *)malloc(sizeof(Node));
    node-&gt;data = val;
    node-&gt;next = NULL;

    if (!list-&gt;head) {
        list-&gt;head = node;
    } else {
        Node *cur = list-&gt;head;
        while (cur-&gt;next) cur = cur-&gt;next;
        cur-&gt;next = node;
    }
    list-&gt;size++;
}

// 删除指定值
void list_remove(LinkedList *list, int val) {
    Node **pp = &amp;list-&gt;head;
    while (*pp) {
        if ((*pp)-&gt;data == val) {
            Node *tmp = *pp;
            *pp = (*pp)-&gt;next;
            free(tmp);
            list-&gt;size--;
            return;
        }
        pp = &amp;(*pp)-&gt;next;
    }
}

// 反转
void list_reverse(LinkedList *list) {
    Node *prev = NULL, *cur = list-&gt;head, *next;
    while (cur) {
        next = cur-&gt;next;
        cur-&gt;next = prev;
        prev = cur;
        cur = next;
    }
    list-&gt;head = prev;
}

// 打印
void list_print(LinkedList *list) {
    Node *cur = list-&gt;head;
    while (cur) {
        printf("%d → ", cur-&gt;data);
        cur = cur-&gt;next;
    }
    printf("NULL (size=%d)\n", list-&gt;size);
}

// 释放
void list_free(LinkedList *list) {
    Node *cur = list-&gt;head;
    while (cur) {
        Node *tmp = cur;
        cur = cur-&gt;next;
        free(tmp);
    }
    list-&gt;head = NULL;
    list-&gt;size = 0;
}

int main(void)
{
    LinkedList list;
    list_init(&amp;list);

    list_push_back(&amp;list, 10);
    list_push_back(&amp;list, 20);
    list_push_back(&amp;list, 30);
    list_push_front(&amp;list, 5);
    list_print(&amp;list);  // 5 → 10 → 20 → 30 → NULL

    list_remove(&amp;list, 20);
    list_print(&amp;list);  // 5 → 10 → 30 → NULL

    list_reverse(&amp;list);
    list_print(&amp;list);  // 30 → 10 → 5 → NULL

    list_free(&amp;list);
    return 0;
}
</code></pre>

hashtable.c<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

#define TABLE_SIZE 16

typedef struct Entry {
    char *key;
    int value;
    struct Entry *next;
} Entry;

typedef struct {
    Entry *buckets[TABLE_SIZE];
} HashTable;

// 简单哈希函数
unsigned int hash(const char *key)
{
    unsigned int h = 0;
    while (*key) {
        h = h * 31 + *key;
        key++;
    }
    return h % TABLE_SIZE;
}

HashTable *ht_create(void)
{
    HashTable *ht = (HashTable *)calloc(1, sizeof(HashTable));
    return ht;
}

// 插入或更新
void ht_set(HashTable *ht, const char *key, int value)
{
    unsigned int idx = hash(key);
    Entry *cur = ht-&gt;buckets[idx];

    while (cur) {
        if (strcmp(cur-&gt;key, key) == 0) {
            cur-&gt;value = value;  // 更新
            return;
        }
        cur = cur-&gt;next;
    }

    // 新建节点（头插法）
    Entry *entry = (Entry *)malloc(sizeof(Entry));
    entry-&gt;key = strdup(key);
    entry-&gt;value = value;
    entry-&gt;next = ht-&gt;buckets[idx];
    ht-&gt;buckets[idx] = entry;
}

// 查找
int ht_get(HashTable *ht, const char *key, int *value)
{
    unsigned int idx = hash(key);
    Entry *cur = ht-&gt;buckets[idx];

    while (cur) {
        if (strcmp(cur-&gt;key, key) == 0) {
            *value = cur-&gt;value;
            return 1;  // 找到
        }
        cur = cur-&gt;next;
    }
    return 0;  // 未找到
}

// 释放
void ht_free(HashTable *ht)
{
    for (int i = 0; i &lt; TABLE_SIZE; i++) {
        Entry *cur = ht-&gt;buckets[i];
        while (cur) {
            Entry *tmp = cur;
            cur = cur-&gt;next;
            free(tmp-&gt;key);
            free(tmp);
        }
    }
    free(ht);
}

int main(void)
{
    HashTable *ht = ht_create();

    ht_set(ht, "apple", 5);
    ht_set(ht, "banana", 3);
    ht_set(ht, "cherry", 8);

    int val;
    if (ht_get(ht, "banana", &amp;val)) {
        printf("banana = %d\n", val);  // 3
    }

    ht_free(ht);
    return 0;
}
</code></pre>

